 53→    53→/// Run an async future with a timeout on the tokio runtime.
 54→    54→/// Prevents filesystem thread hangs from indefinite network I/O.
 55→    55→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 56→    56→fn block_with_timeout<F, T>(rt: &tokio::runtime::Handle, fut: F) -> Result<T, String>
 57→    57→where
 58→    58→    F: std::future::Future<Output = Result<T, String>>,
 59→    59→{
 60→    60→    rt.block_on(async {
 61→    61→        match tokio::time::timeout(NETWORK_TIMEOUT, fut).await {
 62→    62→            Ok(result) => result,
 63→    63→            Err(_) => Err("Operation timed out".to_string()),
 64→    64→        }
 65→    65→    })
 66→    66→}
