108→   108→/// Coordinates IPNS publish operations to prevent sequence number races
109→   109→/// and maintain a monotonic sequence number cache per IPNS name.
110→   110→///
111→   111→/// Shared via `Arc` between `CipherBoxFS` and background publish threads.
112→   112→#[cfg(any(feature = "fuse", feature = "winfsp"))]
113→   113→pub struct PublishCoordinator {
114→   114→    /// Per-IPNS-name sequence number cache (monotonically increasing).
115→   115→    seq_cache: std::sync::Mutex<HashMap<String, u64>>,
116→   116→    /// Per-IPNS-name publish locks to serialize concurrent publishes.
117→   117→    publish_locks: std::sync::Mutex<HashMap<String, Arc<tokio::sync::Mutex<()>>>>,
118→   118→}
119→   119→
120→   120→#[cfg(any(feature = "fuse", feature = "winfsp"))]
121→   121→impl PublishCoordinator {
122→   122→    pub fn new() -> Self {
123→   123→        Self {
124→   124→            seq_cache: std::sync::Mutex::new(HashMap::new()),
125→   125→            publish_locks: std::sync::Mutex::new(HashMap::new()),
126→   126→        }
127→   127→    }
128→   128→
129→   129→    /// Get or create a per-folder publish lock.
130→   130→    pub fn get_lock(&self, ipns_name: &str) -> Arc<tokio::sync::Mutex<()>> {
131→   131→        let mut locks = self.publish_locks.lock().unwrap();
132→   132→        locks
133→   133→            .entry(ipns_name.to_string())
134→   134→            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
135→   135→            .clone()
136→   136→    }
137→   137→
138→   138→    /// Resolve current sequence number with monotonic cache fallback.
139→   139→    ///
140→   140→    /// - On successful resolve: returns max(resolved, cached)
141→   141→    /// - On failed resolve with cached value: returns cached value with warning
142→   142→    /// - On failed resolve with no cache: returns error (prevents seq rollback)
143→   143→    pub async fn resolve_sequence(
144→   144→        &self,
145→   145→        api: &crate::api::client::ApiClient,
146→   146→        ipns_name: &str,
147→   147→    ) -> Result<u64, String> {
148→   148→        match crate::api::ipns::resolve_ipns(api, ipns_name).await {
149→   149→            Ok(resp) => {
150→   150→                let resolved = match resp.sequence_number.parse::<u64>() {
151→   151→                    Ok(v) => v,
152→   152→                    Err(e) => {
153→   153→                        log::warn!(
154→   154→                            "Failed to parse IPNS sequence '{}' for {}: {}",
155→   155→                            resp.sequence_number, ipns_name, e
156→   156→                        );
157→   157→                        0
158→   158→                    }
159→   159→                };
160→   160→                let cached = self.get_cached(ipns_name).unwrap_or(0);
161→   161→                let seq = std::cmp::max(resolved, cached);
162→   162→                self.update_cache(ipns_name, seq);
163→   163→                Ok(seq)
164→   164→            }
165→   165→            Err(e) => match self.get_cached(ipns_name) {
166→   166→                Some(cached) => {
167→   167→                    log::warn!(
168→   168→                        "IPNS resolve failed for {}, using cached seq {}: {}",
169→   169→                        ipns_name,
170→   170→                        cached,
171→   171→                        e
172→   172→                    );
173→   173→                    Ok(cached)
174→   174→                }
175→   175→                None => Err(format!(
176→   176→                    "IPNS resolve failed and no cached sequence for {}: {}",
177→   177→                    ipns_name, e
178→   178→                )),
179→   179→            },
180→   180→        }
181→   181→    }
182→   182→
183→   183→    /// Record a successful publish — cache is monotonic (only increases).
184→   184→    pub fn record_publish(&self, ipns_name: &str, published_seq: u64) {
185→   185→        self.update_cache(ipns_name, published_seq);
186→   186→    }
187→   187→
188→   188→    fn get_cached(&self, ipns_name: &str) -> Option<u64> {
189→   189→        self.seq_cache.lock().unwrap().get(ipns_name).copied()
190→   190→    }
191→   191→
192→   192→    fn update_cache(&self, ipns_name: &str, seq: u64) {
193→   193→        let mut cache = self.seq_cache.lock().unwrap();
194→   194→        let entry = cache.entry(ipns_name.to_string()).or_insert(0);
195→   195→        if seq > *entry {
196→   196→            *entry = seq;
197→   197→        }
198→   198→    }
199→   199→}
