128→/**
129→ * Request an email OTP from the CipherBox backend.
130→ * Returns immediately after the OTP is sent -- the user must check their email.
131→ */
132→export async function requestEmailOtp(email: string): Promise<void> {
133→  const resp = await fetch(`${API_BASE}/auth/identity/email/send-otp`, {
134→    method: 'POST',
135→    headers: { 'Content-Type': 'application/json' },
136→    body: JSON.stringify({ email: email.toLowerCase().trim() }),
137→  });
138→  if (!resp.ok) {
139→    if (resp.status === 429) {
140→      throw new Error('Too many attempts. Please wait before trying again.');
141→    }
142→    throw new Error('Failed to send verification code');
143→  }
144→}
