//! Tauri IPC commands for the desktop auth flow.
//!
//! These commands are invoked from the webview (TypeScript) via Tauri's
//! `invoke()` API. They handle authentication, vault key decryption,
//! Keychain storage, and logout.

use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;
use tauri::{Manager, State};

/// Counter for unique OAuth popup window labels (shared with tray handler).
static POPUP_COUNTER: AtomicU32 = AtomicU32::new(0);

use zeroize::Zeroizing;

use crate::api::{auth, types};
use crate::crypto;
use crate::state::AppState;

/// Handle completed Web3Auth authentication from the webview.
///
/// Called after the webview has completed the Web3Auth SDK flow and obtained
/// an idToken and the user's secp256k1 private key. This command:
/// 1. Sends idToken to backend to get access + refresh tokens
/// 2. Stores refresh token in macOS Keychain
/// 3. Stores private key and derived public key in AppState (memory only)
/// 4. Fetches and decrypts vault keys (including root IPNS keypair)
#[tauri::command]
pub async fn handle_auth_complete(
    app: tauri::AppHandle,
    state: State<'_, AppState>,
    id_token: String,
    private_key: String,
) -> Result<(), String> {
    log::info!("Handling auth completion from webview");

    // Update tray status: Mounting (auth in progress, about to mount)
    let _ = crate::tray::update_tray_status(&app, &crate::tray::TrayStatus::Mounting);

    // 1. Convert private key from hex to bytes and derive public key
    //    (needed for the login request)
    let private_key_hex = if private_key.starts_with("0x") {
        &private_key[2..]
    } else {
        &private_key
    };
    let private_key_bytes =
        hex::decode(private_key_hex).map_err(|_| "Invalid private key hex".to_string())?;
    if private_key_bytes.len() != 32 {
        return Err("Private key must be 32 bytes".to_string());
    }

    // Derive uncompressed public key from private key (65 bytes, 0x04 prefix)
    // Used for both ECIES operations and backend auth (backend expects uncompressed)
    let public_key_bytes = derive_public_key(&private_key_bytes)?;
    let public_key_hex = hex::encode(&public_key_bytes); // 130 hex chars

    // 2. Login with backend (requires uncompressed publicKey, 130 hex chars)
    let login_req = types::LoginRequest {
        id_token: id_token.clone(),
        public_key: public_key_hex,
        login_type: "corekit".to_string(),
    };

    let resp = state
        .api
        .post("/auth/login", &login_req)
        .await
        .map_err(|e| format!("Login request failed: {}", e))?;

    if !resp.status().is_success() {
        let status = resp.status();
        let body = resp.text().await.unwrap_or_default();
        return Err(format!("Login failed ({}): {}", status, body));
    }

    let login_resp: types::LoginResponse = resp
        .json()
        .await
        .map_err(|e| format!("Failed to parse login response: {}", e))?;

    // Delegate to shared post-auth setup
    complete_auth_setup(
        &app,
        &state,
        login_resp.access_token,
        login_resp.refresh_token,
        Zeroizing::new(private_key_bytes),
        public_key_bytes,
        login_resp.is_new_user,
        false,
    )
    .await
}

/// Shared post-auth setup used by both `handle_auth_complete` and `handle_test_login_complete`.
///
/// Stores tokens and keys, initializes/fetches vault, registers device, mounts FUSE,
/// and hides the login window.
async fn complete_auth_setup(
    app: &tauri::AppHandle,
    state: &AppState,
    access_token: String,
    refresh_token: String,
    private_key_bytes: Zeroizing<Vec<u8>>,
    public_key_bytes: Vec<u8>,
    is_new_user: bool,
    skip_keychain: bool,
) -> Result<(), String> {
    // 1. Store access token in API client
    state.api.set_access_token(access_token.clone()).await;

    // 2. Extract user ID from JWT claims (decode payload, read `sub`)
    let user_id = extract_user_id_from_jwt(&access_token)?;
    *state.user_id.write().await = Some(user_id.clone());

    // 3. Store refresh token in Keychain (skip in test-login mode to avoid popups)
    if !skip_keychain {
        auth::store_refresh_token(&user_id, &refresh_token)
            .map_err(|e| format!("Keychain store failed: {}", e))?;
        auth::store_user_id(&user_id)
            .map_err(|e| format!("Keychain store user ID failed: {}", e))?;
    } else {
        log::info!("Skipping Keychain storage (test-login mode)");
    }

    // 4. Store keys in AppState
    *state.private_key.write().await = Some(private_key_bytes.to_vec());
    *state.public_key.write().await = Some(public_key_bytes.clone());

    // 5. Initialize vault for new users, or fetch existing vault
    //    Also handle the edge case where user exists but vault was deleted.
    if is_new_user {
        log::info!("New user detected, initializing vault");
        initialize_vault(state, &public_key_bytes).await?;
    }
    match fetch_and_decrypt_vault(state).await {
        Ok(()) => {}
        Err(e) if e.contains("404") && !is_new_user => {
            log::warn!("Vault not found for existing user, re-initializing");
            initialize_vault(state, &public_key_bytes).await?;
            fetch_and_decrypt_vault(state).await?;
        }
        Err(e) => return Err(e),
    }

    // 6. Mark as authenticated
    *state.is_authenticated.write().await = true;

    // 7. Mount filesystem (or just mark as synced if no filesystem feature enabled)
    // NOTE: Device registry spawn moved AFTER mount to avoid concurrent HTTP
    //       requests that cause reqwest connection pool starvation during pre-populate.
    #[cfg(not(any(feature = "fuse", feature = "winfsp")))]
    {
        let _ = crate::tray::update_tray_status(app, &crate::tray::TrayStatus::Synced);
    }
    #[cfg(any(feature = "fuse", feature = "winfsp"))]
    {
        *state.mount_status.write().await = crate::state::MountStatus::Mounting;
        let private_key = state
            .private_key
            .read()
            .await
            .as_ref()
            .ok_or("Private key not available for filesystem mount")?
            .clone();
        let public_key = state
            .public_key
            .read()
            .await
            .as_ref()
            .ok_or("Public key not available for filesystem mount")?
            .clone();
        let root_folder_key = state
            .root_folder_key
            .read()
            .await
            .as_ref()
            .ok_or("Root folder key not available for filesystem mount")?
            .clone();
        let root_ipns_name = state
            .root_ipns_name
            .read()
            .await
            .as_ref()
            .ok_or("Root IPNS name not available for filesystem mount")?
            .clone();
        let root_ipns_private_key = state.root_ipns_private_key.read().await.clone();

        // Extract TEE keys for new folder creation
        let tee_keys = state.tee_keys.read().await;
        let tee_public_key = tee_keys.as_ref().and_then(|tk| {
            hex::decode(&tk.current_public_key).ok()
        });
        let tee_key_epoch = tee_keys.as_ref().map(|tk| tk.current_epoch);
        drop(tee_keys);

        let rt = tokio::runtime::Handle::current();
        match crate::fuse::mount_filesystem(
            state,
            rt,
            private_key,
            public_key,
            root_folder_key,
            root_ipns_name,
            root_ipns_private_key,
            tee_public_key,
            tee_key_epoch,
        ).await {
            Ok(_handle) => {
                *state.mount_status.write().await = crate::state::MountStatus::Mounted;
                let _ = crate::tray::update_tray_status(app, &crate::tray::TrayStatus::Synced);
                log::info!("Filesystem mounted at {}", crate::fuse::mount_point().display());
            }
            Err(e) => {
                let err_msg = format!("Filesystem mount failed: {}", e);
                *state.mount_status.write().await =
                    crate::state::MountStatus::Error(err_msg.clone());
                let _ = crate::tray::update_tray_status(
                    app,
                    &crate::tray::TrayStatus::Error(err_msg.clone()),
                );
                log::error!("{}", err_msg);
                // Don't fail auth -- user is authenticated but mount failed
            }
        }
    }

    // 8. Register device in encrypted registry (non-blocking, after mount)
    {
        let reg_api = state.api.clone();
        let reg_private_key = Zeroizing::new(private_key_bytes.to_vec());
        let reg_public_key = public_key_bytes.clone();
        let reg_user_id = user_id.clone();
        tokio::spawn(async move {
            let pk_arr: [u8; 32] = match reg_private_key.as_slice().try_into() {
                Ok(arr) => arr,
                Err(_) => {
                    log::warn!("Device registry: invalid private key length");
                    return;
                }
            };
            match crate::registry::register_device(
                &reg_api,
                &pk_arr,
                &reg_public_key,
                &reg_user_id,
            )
            .await
            {
                Ok(()) => log::info!("Device registry updated"),
                Err(e) => log::warn!("Device registry update failed (non-blocking): {}", e),
            }
        });
    }

    // Close OAuth popup windows and hide the login webview
    for (label, window) in app.webview_windows() {
        if label.starts_with("oauth-popup-") {
            let _ = window.destroy();
        } else if label == "main" {
            let _ = window.hide();
        }
    }

    log::info!("Authentication complete for user {}", user_id);
    Ok(())
}

/// Handle session restore when Core Kit has a restored LOGGED_IN session.
///
/// Called when Core Kit's init() restores a previous session from localStorage
/// and the Rust side already has a valid access token from silent refresh.
/// Unlike `handle_auth_complete`, this skips the `/auth/login` POST since
/// tokens are already valid.
#[tauri::command]
pub async fn handle_session_restore(
    app: tauri::AppHandle,
    state: State<'_, AppState>,
    private_key: String,
) -> Result<(), String> {
    log::info!("Handling session restore from Core Kit");

    let _ = crate::tray::update_tray_status(&app, &crate::tray::TrayStatus::Mounting);

    // Convert private key from hex to bytes
    let private_key_hex = if private_key.starts_with("0x") {
        &private_key[2..]
    } else {
        &private_key
    };
    let private_key_bytes =
        hex::decode(private_key_hex).map_err(|_| "Invalid private key hex".to_string())?;
    if private_key_bytes.len() != 32 {
        return Err("Private key must be 32 bytes".to_string());
    }

    let public_key_bytes = derive_public_key(&private_key_bytes)?;

    // Get the existing access token (set by try_silent_refresh)
    let access_token = state
        .api
        .get_access_token()
        .await
        .ok_or("No access token available - silent refresh may not have succeeded")?;

    // Extract user_id from the existing access token to look up the refresh token
    let user_id = extract_user_id_from_jwt(&access_token)?;
    let refresh_token = auth::get_refresh_token(&user_id)
        .map_err(|e| format!("Keychain read failed: {}", e))?
        .ok_or("No refresh token in Keychain")?;

    complete_auth_setup(
        &app,
        &state,
        access_token,
        refresh_token,
        Zeroizing::new(private_key_bytes),
        public_key_bytes,
        false, // not a new user
        true,  // skip Keychain writes (already stored)
    )
    .await
}

/// Try to silently refresh the session from a Keychain-stored refresh token.
///
/// On cold start, the private key is NOT available (it requires Web3Auth login).
/// This command refreshes the API session tokens only. The webview still needs
/// to complete Web3Auth login to obtain the private key for vault decryption.
///
/// Returns `true` if the API session was refreshed successfully.
/// Returns `false` if no stored session exists or refresh failed.
#[tauri::command]
pub async fn try_silent_refresh(state: State<'_, AppState>) -> Result<bool, String> {
    log::info!("Attempting silent refresh from Keychain");

    // Check for stored user ID
    let user_id = match auth::get_last_user_id() {
        Ok(Some(id)) => id,
        Ok(None) => {
            log::info!("No stored user ID, silent refresh skipped");
            return Ok(false);
        }
        Err(e) => {
            log::warn!("Failed to read user ID from Keychain: {}", e);
            return Ok(false);
        }
    };

    // Get refresh token from Keychain
    let refresh_token = match auth::get_refresh_token(&user_id) {
        Ok(Some(token)) => token,
        Ok(None) => {
            log::info!("No stored refresh token for user {}", user_id);
            return Ok(false);
        }
        Err(e) => {
            log::warn!("Failed to read refresh token from Keychain: {}", e);
            return Ok(false);
        }
    };

    // POST /auth/refresh with the stored refresh token
    let refresh_req = types::RefreshRequest {
        refresh_token: refresh_token.clone(),
    };

    let resp = match state.api.post("/auth/refresh", &refresh_req).await {
        Ok(r) => r,
        Err(e) => {
            log::warn!("Refresh request failed (network error): {}", e);
            return Ok(false);
        }
    };

    if resp.status().as_u16() == 401 {
        // Stale token -- delete from Keychain
        log::info!("Refresh token expired, clearing Keychain");
        let _ = auth::delete_refresh_token(&user_id);
        return Ok(false);
    }

    if !resp.status().is_success() {
        log::warn!("Refresh failed with status {}", resp.status());
        return Ok(false);
    }

    let refresh_resp: types::RefreshResponse = resp
        .json()
        .await
        .map_err(|e| format!("Failed to parse refresh response: {}", e))?;

    // Store new tokens
    state.api.set_access_token(refresh_resp.access_token).await;
    auth::store_refresh_token(&user_id, &refresh_resp.refresh_token)
        .map_err(|e| format!("Keychain store failed: {}", e))?;
    *state.user_id.write().await = Some(user_id.clone());

    log::info!("Silent refresh successful for user {}", user_id);

    // NOTE: Private key is NOT restored by silent refresh.
    // The webview must complete Web3Auth login to get the private key.
    // is_authenticated remains false until handle_auth_complete is called.
    Ok(true)
}

/// Start the background sync daemon.
///
/// Called from the webview after successful auth + mount. Creates the sync channel,
/// stores the sender in AppState for the tray menu, and spawns the daemon.
#[tauri::command]
pub async fn start_sync_daemon(
    app: tauri::AppHandle,
    state: State<'_, AppState>,
) -> Result<(), String> {
    log::info!("Starting background sync daemon");

    let (tx, rx) = tokio::sync::mpsc::channel::<()>(1);

    // Store the sender in AppState so the tray "Sync Now" button can trigger syncs
    if let Ok(mut guard) = state.sync_trigger.write() {
        *guard = Some(tx);
    }

    // Extract shared references the daemon needs from AppState.
    // AppState fields are RwLock which we wrap in Arc for shared ownership
    // between the daemon task and the Tauri-managed state.
    //
    // We use the AppHandle to get the managed state which is already Arc-wrapped by Tauri.
    // The daemon reads root_ipns_name and is_authenticated via the app handle's state.
    let api = state.api.clone();
    let app_handle = app.clone();

    // Get the root IPNS name -- daemon needs to read it periodically
    let root_ipns_name = state.root_ipns_name.read().await.clone();

    // Clone values for the daemon's owned copies
    let root_ipns_name_lock = Arc::new(tokio::sync::RwLock::new(root_ipns_name));
    let is_authenticated_lock = Arc::new(tokio::sync::RwLock::new(
        *state.is_authenticated.read().await,
    ));

    // Spawn sync state bridge: periodically sync auth/ipns state from AppState to daemon
    let bridge_app = app.clone();
    let bridge_root = root_ipns_name_lock.clone();
    let bridge_auth = is_authenticated_lock.clone();
    tokio::spawn(async move {
        loop {
            tokio::time::sleep(std::time::Duration::from_secs(5)).await;
            let state = bridge_app.state::<AppState>();
            *bridge_root.write().await = state.root_ipns_name.read().await.clone();
            *bridge_auth.write().await = *state.is_authenticated.read().await;
        }
    });

    tokio::spawn(async move {
        let mut daemon = crate::sync::SyncDaemon::new(
            api,
            root_ipns_name_lock,
            is_authenticated_lock,
            rx,
            app_handle,
        );
        daemon.run().await;
    });

    log::info!("Sync daemon spawned");
    Ok(())
}

/// Get the dev-key if one was provided via CLI (debug builds only).
///
/// Returns `Some(hex_string)` if `--dev-key` was passed at startup, `None` otherwise.
/// The webview can use this to skip Web3Auth login and call `handle_auth_complete`
/// directly with a synthetic identity token or via the test-login endpoint.
#[tauri::command]
pub async fn get_dev_key(state: State<'_, AppState>) -> Result<Option<String>, String> {
    Ok(state.dev_key.read().await.clone())
}

/// Handle test-login authentication (debug builds only).
///
/// Called from the webview after a successful `POST /auth/test-login` response.
/// Unlike `handle_auth_complete`, this skips the `/auth/login` POST because
/// test-login already returns access + refresh tokens directly.
///
/// The private key comes from the test-login response (server-generated
/// deterministic keypair), NOT from the CLI `--dev-key` argument.
#[cfg(debug_assertions)]
#[tauri::command]
pub async fn handle_test_login_complete(
    app: tauri::AppHandle,
    state: State<'_, AppState>,
    access_token: String,
    refresh_token: String,
    private_key_hex: String,
    is_new_user: bool,
) -> Result<(), String> {
    log::info!("Handling test-login auth completion (debug mode)");

    // Update tray status: Mounting
    let _ = crate::tray::update_tray_status(&app, &crate::tray::TrayStatus::Mounting);

    // Convert private key hex to bytes
    let pk_hex = if private_key_hex.starts_with("0x") {
        &private_key_hex[2..]
    } else {
        &private_key_hex
    };
    let private_key_bytes =
        hex::decode(pk_hex).map_err(|_| "Invalid private key hex from test-login".to_string())?;
    if private_key_bytes.len() != 32 {
        return Err("Private key must be 32 bytes".to_string());
    }

    // Derive public key from the test-login private key
    let public_key_bytes = derive_public_key(&private_key_bytes)?;

    // Delegate to shared post-auth setup (skips /auth/login POST and Keychain)
    complete_auth_setup(
        &app,
        &state,
        access_token,
        refresh_token,
        Zeroizing::new(private_key_bytes),
        public_key_bytes,
        is_new_user,
        true, // skip Keychain — test-login re-authenticates each time
    )
    .await
}

/// Open an OAuth popup window directly from Rust.
///
/// Bypasses `window.open()` which is unreliable on Windows WebView2 (the
/// `NewWindowRequested` event / `on_new_window` handler may silently fail).
/// Instead, the webview calls this command via `invoke()` to create a new
/// Tauri webview window pointing directly at the OAuth URL.
#[tauri::command]
pub async fn open_oauth_popup(app: tauri::AppHandle, url: String) -> Result<(), String> {
    let n = POPUP_COUNTER.fetch_add(1, Ordering::Relaxed);
    let label = format!("oauth-popup-{}", n);

    let parsed_url: tauri::Url = url
        .parse()
        .map_err(|e| format!("Invalid OAuth URL: {}", e))?;

    // Allowlist: only HTTPS requests to known OAuth providers are permitted.
    const ALLOWED_HOSTS: &[&str] = &["accounts.google.com"];
    if parsed_url.scheme() != "https" {
        return Err("OAuth URL must use HTTPS".to_string());
    }
    let host = parsed_url.host_str().unwrap_or("");
    if !ALLOWED_HOSTS.contains(&host) {
        return Err(format!("OAuth URL host '{}' is not allowed", host));
    }

    log::info!("Creating OAuth popup window: {} -> {}", label, host);

    tauri::WebviewWindowBuilder::new(
        &app,
        &label,
        tauri::WebviewUrl::External(parsed_url),
    )
    .title("Sign in with Google")
    .inner_size(500.0, 700.0)
    .center()
    .build()
    .map_err(|e| format!("Failed to create OAuth popup: {}", e))?;

    Ok(())
}

/// Logout: invalidate session, clear Keychain, zero all sensitive keys.
#[tauri::command]
pub async fn logout(app: tauri::AppHandle, state: State<'_, AppState>) -> Result<(), String> {
    log::info!("Logging out");

    // Unmount filesystem before clearing keys
    #[cfg(any(feature = "fuse", feature = "winfsp"))]
    {
        if let Err(e) = crate::fuse::unmount_filesystem() {
            log::warn!("Filesystem unmount failed (will continue logout): {}", e);
        }
        *state.mount_status.write().await = crate::state::MountStatus::Unmounted;
    }

    // POST /auth/logout (best-effort, don't fail logout if server unreachable)
    let resp = state.api.authenticated_post("/auth/logout", &()).await;
    if let Err(e) = resp {
        log::warn!("Logout request failed (will continue local cleanup): {}", e);
    }

    // Delete refresh token from Keychain
    if let Some(ref user_id) = *state.user_id.read().await {
        let _ = auth::delete_refresh_token(user_id);
    }

    // Zero all sensitive keys in memory
    state.clear_keys().await;

    // Update tray status
    let _ = crate::tray::update_tray_status(&app, &crate::tray::TrayStatus::NotConnected);

    log::info!("Logout complete");
    Ok(())
}

/// Initialize a new vault for a first-time user.
///
/// Generates a root folder AES-256 key and derives a deterministic Ed25519 IPNS
/// keypair via HKDF from the user's private key. ECIES-wraps them with the
/// user's secp256k1 public key, and POSTs everything to `/vault/init`.
async fn initialize_vault(state: &AppState, public_key: &[u8]) -> Result<(), String> {
    // Generate root folder AES-256 key (32 random bytes)
    let root_folder_key = crypto::utils::generate_random_bytes(32);

    // Derive IPNS keypair deterministically via HKDF from user's private key
    let private_key = state
        .private_key
        .read()
        .await
        .as_ref()
        .ok_or("Private key not available for vault IPNS derivation")?
        .clone();
    let private_key_arr: [u8; 32] = private_key
        .as_slice()
        .try_into()
        .map_err(|_| "Invalid private key length")?;
    let (ipns_private_key, _ipns_public_key, root_ipns_name) =
        crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr)
            .map_err(|e| format!("Vault IPNS derivation failed: {:?}", e))?;

    // ECIES-wrap keys with user's uncompressed secp256k1 public key
    let encrypted_root_folder_key = crypto::ecies::wrap_key(&root_folder_key, public_key)
        .map_err(|e| format!("Failed to wrap root folder key: {}", e))?;
    let encrypted_ipns_private_key = crypto::ecies::wrap_key(&ipns_private_key, public_key)
        .map_err(|e| format!("Failed to wrap IPNS private key: {}", e))?;

    // 1. Register vault with backend
    let init_req = types::InitVaultRequest {
        owner_public_key: hex::encode(public_key),
        encrypted_root_folder_key: hex::encode(&encrypted_root_folder_key),
        encrypted_root_ipns_private_key: hex::encode(&encrypted_ipns_private_key),
        root_ipns_name: root_ipns_name.clone(),
    };

    let resp = state
        .api
        .authenticated_post("/vault/init", &init_req)
        .await
        .map_err(|e| format!("Vault init request failed: {}", e))?;

    if !resp.status().is_success() {
        let status = resp.status();
        let body = resp.text().await.unwrap_or_default();
        return Err(format!("Vault init failed ({}): {}", status, body));
    }

    // 2. Create and publish initial empty folder metadata
    //    Without this, FUSE init() can't resolve the root IPNS name.
    log::info!("Publishing initial empty root folder metadata");

    let empty_metadata = crypto::folder::FolderMetadata {
        version: "v2".to_string(),
        children: vec![],
    };

    // Encrypt metadata with root folder key
    let folder_key_arr: [u8; 32] = root_folder_key
        .try_into()
        .map_err(|_| "Invalid root folder key length".to_string())?;
    let sealed = crypto::folder::encrypt_folder_metadata(&empty_metadata, &folder_key_arr)
        .map_err(|e| format!("Metadata encryption failed: {}", e))?;

    // Format as JSON { "iv": "<hex>", "data": "<base64>" }
    let iv_hex = hex::encode(&sealed[..12]);
    use base64::Engine;
    let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
    let json_metadata = serde_json::json!({
        "iv": iv_hex,
        "data": data_base64,
    });
    let json_bytes = serde_json::to_vec(&json_metadata)
        .map_err(|e| format!("JSON serialization failed: {}", e))?;

    // Upload encrypted metadata to IPFS
    let initial_cid = crate::api::ipfs::upload_content(&state.api, &json_bytes).await?;

    // Create and sign IPNS record (sequence 0, 24h lifetime)
    let ipns_key_arr: [u8; 32] = ipns_private_key.as_slice()
        .try_into()
        .map_err(|_| "Invalid IPNS private key length".to_string())?;
    let value = format!("/ipfs/{}", initial_cid);
    let record = crypto::ipns::create_ipns_record(&ipns_key_arr, &value, 0, 86_400_000)
        .map_err(|e| format!("IPNS record creation failed: {}", e))?;
    let marshaled = crypto::ipns::marshal_ipns_record(&record)
        .map_err(|e| format!("IPNS record marshaling failed: {}", e))?;
    let record_base64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);

    // Publish IPNS record via backend
    let publish_req = crate::api::ipns::IpnsPublishRequest {
        ipns_name: root_ipns_name.clone(),
        record: record_base64,
        metadata_cid: initial_cid,
        encrypted_ipns_private_key: None,
        key_epoch: None,
    };
    crate::api::ipns::publish_ipns(&state.api, &publish_req).await?;

    log::info!("Vault initialized and root metadata published for new user");
    Ok(())
}

/// Fetch vault keys from backend and decrypt them using the user's private key.
///
/// Decrypts:
/// - Root folder AES-256 key (32 bytes) from ECIES-wrapped hex
/// - Root IPNS Ed25519 private key (32 bytes) from ECIES-wrapped hex
///
/// The IPNS public key is derivable from the private key if ever needed.
/// Stores all keys in AppState (memory only).
async fn fetch_and_decrypt_vault(state: &AppState) -> Result<(), String> {
    log::info!("Fetching and decrypting vault keys");

    // GET /vault
    let resp = state
        .api
        .authenticated_get("/vault")
        .await
        .map_err(|e| format!("Vault fetch failed: {}", e))?;

    if !resp.status().is_success() {
        let status = resp.status();
        let body = resp.text().await.unwrap_or_default();
        return Err(format!("Vault fetch failed ({}): {}", status, body));
    }

    let vault: types::VaultResponse = resp
        .json()
        .await
        .map_err(|e| format!("Failed to parse vault response: {}", e))?;

    // Get private key for decryption
    let private_key = state
        .private_key
        .read()
        .await
        .as_ref()
        .ok_or("Private key not available for vault decryption")?
        .clone();

    // Decrypt root folder key
    let encrypted_root_folder_key = hex::decode(&vault.encrypted_root_folder_key)
        .map_err(|_| "Invalid encryptedRootFolderKey hex")?;
    let root_folder_key = crypto::ecies::unwrap_key(&encrypted_root_folder_key, &private_key)
        .map_err(|e| format!("Failed to decrypt root folder key: {}", e))?;
    *state.root_folder_key.write().await = Some(root_folder_key);

    // Decrypt root IPNS private key
    let encrypted_root_ipns_private_key = hex::decode(&vault.encrypted_root_ipns_private_key)
        .map_err(|_| "Invalid encryptedRootIpnsPrivateKey hex")?;
    let root_ipns_private_key =
        crypto::ecies::unwrap_key(&encrypted_root_ipns_private_key, &private_key)
            .map_err(|e| format!("Failed to decrypt root IPNS private key: {}", e))?;

    // Verify stored IPNS key matches HKDF derivation (consistency check)
    let private_key_arr: [u8; 32] = private_key
        .as_slice()
        .try_into()
        .map_err(|_| "Invalid private key length for HKDF check")?;
    if let Ok((expected_ipns_key, _, _)) = crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr) {
        if root_ipns_private_key != *expected_ipns_key {
            log::warn!("Vault IPNS key mismatch: stored key differs from HKDF derivation");
            // Don't block - proceed with stored key for backward compatibility
        }
    }

    *state.root_ipns_private_key.write().await = Some(root_ipns_private_key);

    // Store IPNS name and TEE keys
    *state.root_ipns_name.write().await = Some(vault.root_ipns_name);
    *state.tee_keys.write().await = vault.tee_keys;

    log::info!("Vault keys decrypted and stored in memory");
    Ok(())
}

/// Extract the user ID (`sub` claim) from a JWT access token.
///
/// Decodes the JWT payload (base64url) without verification -- the server
/// already verified the token, we just need the `sub` field for Keychain lookup.
fn extract_user_id_from_jwt(token: &str) -> Result<String, String> {
    let parts: Vec<&str> = token.split('.').collect();
    if parts.len() != 3 {
        return Err("Invalid JWT format".to_string());
    }

    // Decode the payload (second part) -- base64url encoding
    let payload = parts[1];
    // base64url: replace - with + and _ with /, then add padding
    let padded = match payload.len() % 4 {
        2 => format!("{}==", payload),
        3 => format!("{}=", payload),
        _ => payload.to_string(),
    };
    let standard = padded.replace('-', "+").replace('_', "/");

    let decoded = base64::Engine::decode(&base64::engine::general_purpose::STANDARD, &standard)
        .map_err(|e| format!("Failed to decode JWT payload: {}", e))?;

    let json: serde_json::Value = serde_json::from_slice(&decoded)
        .map_err(|e| format!("Failed to parse JWT payload: {}", e))?;

    json["sub"]
        .as_str()
        .map(|s| s.to_string())
        .ok_or_else(|| "JWT payload missing 'sub' claim".to_string())
}

/// Derive an uncompressed secp256k1 public key (65 bytes, 0x04 prefix) from a 32-byte private key.
///
/// Used for ECIES encryption/decryption operations.
fn derive_public_key(private_key: &[u8]) -> Result<Vec<u8>, String> {
    let sk = ecies::SecretKey::parse_slice(private_key)
        .map_err(|e| format!("Invalid secp256k1 private key: {:?}", e))?;
    let pk = ecies::PublicKey::from_secret_key(&sk);
    Ok(pk.serialize().to_vec()) // 65-byte uncompressed format
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_extract_user_id_from_jwt() {
        // Create a mock JWT with a known sub claim
        // Header: {"alg":"HS256","typ":"JWT"}
        // Payload: {"sub":"user-123-abc","iat":1700000000}
        let header = base64::Engine::encode(
            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
            b"{\"alg\":\"HS256\",\"typ\":\"JWT\"}",
        );
        let payload = base64::Engine::encode(
            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
            b"{\"sub\":\"user-123-abc\",\"iat\":1700000000}",
        );
        let token = format!("{}.{}.fake-signature", header, payload);

        let user_id = extract_user_id_from_jwt(&token).unwrap();
        assert_eq!(user_id, "user-123-abc");
    }

    #[test]
    fn test_extract_user_id_invalid_jwt() {
        let result = extract_user_id_from_jwt("not-a-jwt");
        assert!(result.is_err());
    }

    #[test]
    fn test_extract_user_id_missing_sub() {
        let header = base64::Engine::encode(
            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
            b"{\"alg\":\"HS256\",\"typ\":\"JWT\"}",
        );
        let payload = base64::Engine::encode(
            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
            b"{\"iat\":1700000000}",
        );
        let token = format!("{}.{}.fake-signature", header, payload);

        let result = extract_user_id_from_jwt(&token);
        assert!(result.is_err());
        assert!(result.unwrap_err().contains("sub"));
    }

    #[test]
    fn test_derive_public_key() {
        // Use a known private key and verify the public key is 65 bytes with 0x04 prefix
        let private_key = hex::decode(
            "ac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80",
        )
        .unwrap();

        let public_key = derive_public_key(&private_key).unwrap();
        assert_eq!(public_key.len(), 65);
        assert_eq!(public_key[0], 0x04); // Uncompressed prefix
    }

    #[test]
    fn test_derive_public_key_invalid_size() {
        let result = derive_public_key(&[0u8; 16]); // Too short
        assert!(result.is_err());
    }
}

